def process(malta_filter):
    neo = malta_filter[malta_filter['Culture'] == 'Neolithic'].copy()
    # Most northern = highest latitude; tie-break by later year (higher date value)
    neo_sorted = neo.sort_values(['Latitude', 'date'], ascending=[False, False])
    top = neo_sorted.iloc[0]
    return neo_sorted[['Site', 'Culture', 'Latitude', 'Longitude', 'date', 'error']].head(10)

def load() -> pd.DataFrame:
    import openpyxl
    wb = openpyxl.load_workbook('data/archeology/input/climateMeasurements.xlsx', read_only=True)
    ws = wb.active
    rows = []
    for i, row in enumerate(ws.iter_rows(values_only=True)):
        rows.append(row)
        if i >= 6:
            break
    wb.close()
    return pd.DataFrame(rows)

